def f_ho(intervals):
    if not intervals: return []
    s = sorted(intervals)
    out = [list(s[0])]
    for lo, hi in s[1:]:
        if lo <= out[-1][1]:
            out[-1][1] = max(out[-1][1], hi)
        else:
            out.append([lo, hi])
    return out

